package cl.acis.ordenes.controller;
import cl.acis.ordenes.config.ActorHeaders; import cl.acis.ordenes.dto.*; import cl.acis.ordenes.model.*; import cl.acis.ordenes.service.OrdenService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/ordenes") public class OrdenController {final OrdenService service;final ActorHeaders headers;public OrdenController(OrdenService s,ActorHeaders h){service=s;headers=h;}
 @PostMapping public OrdenResponse crear(@Valid @RequestBody OrdenRequest r,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);headers.exigir(a,"ADMINISTRADOR","JEFATURA");return service.crear(r,a.id());}
 @GetMapping public List<OrdenResponse> listar(@RequestParam(required=false) EstadoOrden estado,@RequestParam(required=false) Long tecnicoId,@RequestParam(required=false) Long clienteId,@RequestParam(required=false) LocalDate fecha,@RequestParam(required=false) Prioridad prioridad,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);return service.listar(estado,tecnicoId,clienteId,fecha,prioridad,new OrdenService.ActorFilter(a.id(),a.rol()));}
 @GetMapping("/{id}") public OrdenResponse obtener(@PathVariable Long id,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);return service.obtener(id,new OrdenService.ActorFilter(a.id(),a.rol()));}
 @PutMapping("/{id}") public OrdenResponse editar(@PathVariable Long id,@Valid @RequestBody OrdenRequest r,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);return service.editar(id,r,a.id(),a.rol());}
 @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);service.eliminar(id,a.id(),a.rol());return ResponseEntity.noContent().build();}
 @PostMapping("/{id}/acciones") public OrdenResponse accion(@PathVariable Long id,@Valid @RequestBody AccionRequest r,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);return service.accion(id,r,a.rol(),a.id());}
 @GetMapping("/{id}/eventos") public List<EventoResponse> eventos(@PathVariable Long id,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);service.obtener(id,new OrdenService.ActorFilter(a.id(),a.rol()));return service.eventos(id);}
 @GetMapping("/{id}/acciones-disponibles") public Set<AccionOrden> disponibles(@PathVariable Long id,HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);service.obtener(id,new OrdenService.ActorFilter(a.id(),a.rol()));return service.disponibles(id,a.rol(),a.id());}
 @GetMapping("/metricas") public MetricaResponse metricas(HttpServletRequest q){ActorHeaders.Actor a=headers.leer(q);headers.exigir(a,"ADMINISTRADOR","JEFATURA");return service.metricas();}
}
